function mnKey(code){const c=(code||"").toUpperCase();
  if(MANUAL[c])return c;if(/^ADV/.test(c))return"ADV";if(c==="TDS-SAL"||c==="TDS-NON")return"TDS-RET";if(/^PT-/.test(c))return"PT";if(/^LWF-/.test(c))return"LWF";
  if(/^MSME-1/.test(c))return"MSME-1";if(/^FSSAI/.test(c))return"FSSAI";if(/^LIC-/.test(c))return"LIC";return null}
const mx=v=>v?(v[lang]||v.en||v.hi):"";
let mnState={q:""},mnNotes=[],mnNoteRef=null,erCases=[],erRef=null;
function mnInit(db){if(db){mnNoteRef=db.collection("manual_notes");mnNoteRef.onSnapshot(s=>{mnNotes=s.docs.map(d=>Object.assign({id:d.id},d.data()))},()=>{});
    erRef=db.collection("error_cases");erRef.onSnapshot(s=>{erCases=s.docs.map(d=>Object.assign({id:d.id},d.data()));renderMn()},()=>{})}
  else{mnNotes=lget("compliance_mnotes_v1","[]");erCases=lget("compliance_errs_v1","[]")}}
async function mnAddNote(k,text){const n={k,text,by:me.id||"local",at:Date.now()};if(mnNoteRef)await mnNoteRef.add(n);else{n.id="n"+Date.now();mnNotes.push(n);lset("compliance_mnotes_v1",mnNotes)}}
async function erSaveCase(c){if(erRef){if(c.id){const id=c.id,d=Object.assign({},c);delete d.id;await erRef.doc(id).set(d);return id}const r=await erRef.add(c);return r.id}
  if(!c.id)c.id="e"+Date.now();const i=erCases.findIndex(x=>x.id===c.id);if(i>=0)erCases[i]=c;else erCases.push(c);lset("compliance_errs_v1",erCases);return c.id}
function renderMn(){
  const el=$("#mn");if(!el||el.hidden)return;
  const q=mnState.q.trim().toLowerCase();
  const keys=Object.keys(MANUAL).filter(k=>!q||[k,mx(MANUAL[k].what),t("grp_"+MANUAL[k].grp)].join(" ").toLowerCase().includes(q));
  const by={};keys.forEach(k=>(by[MANUAL[k].grp]=by[MANUAL[k].grp]||[]).push(k));
  const open=erCases.filter(c=>!c.solved).length;
  el.innerHTML=`<h2 style="margin-top:4px">${esc(t("mnT"))}</h2><div class="note" style="margin-bottom:10px">${esc(t("mnTxt"))}</div>
   <div class="actions" style="margin:0 0 10px"><button class="btn red" id="erNew" style="flex:1">${esc(t("erB"))}</button><button class="btn ghost" id="erList">${esc(t("erAll"))}${open?` <span class="badge b-late">${open}</span>`:""}</button></div>
   <div class="filters"><input id="mnQ" placeholder="${esc(t("mnSearch"))}" value="${esc(mnState.q)}"></div>
   ${GROUPS.filter(g=>by[g]).map(g=>`<h2>${esc(t("grp_"+g))}</h2>`+by[g].map(k=>`<div class="item mnRow" data-k="${k}"><div class="main"><div class="t">${esc(k==="TDS-RET"?"TDS return (138 / 140)":k==="ADV"?bt("एडवांस टैक्स","Advance tax"):k==="LIC"?bt("लाइसेंस रिन्यूअल","Licence renewal"):k==="PT"?bt("प्रोफ़ेशनल टैक्स","Professional tax"):k==="LWF"?bt("लेबर वेलफ़ेयर फ़ंड","Labour welfare fund"):k==="FSSAI"?"FSSAI D-1 / D-2":k==="TAR"?bt("टैक्स ऑडिट रिपोर्ट","Tax audit report"):k)}</div><div class="m">${esc(mx(MANUAL[k].what))}</div></div><span class="m">›</span></div>`).join("")).join("")||`<div class="empty">${esc(t("nothing"))}</div>`}`;
  const qi=$("#mnQ");qi.oninput=()=>{mnState.q=qi.value;const pos=qi.selectionStart;renderMn();const n=$("#mnQ");n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}};
  el.querySelectorAll(".mnRow").forEach(r=>r.onclick=()=>openManual(r.dataset.k));
  $("#erNew").onclick=()=>openErr(null,null);$("#erList").onclick=openErrList;
}
function openManual(k,itemId){
  const M=MANUAL[k];
  if(!M){openSheet(`<h3>${esc(t("mnHow"))}</h3><div class="empty">${esc(t("mnNone"))}</div><div class="actions"><button class="btn red" id="mnErr">${esc(t("erB"))}</button><button class="btn ghost" id="mnX">${esc(t("close"))}</button></div>`,{k:"manual",id:k,item:itemId});
    $("#mnX").onclick=()=>itemId?openDetail(itemId):closeSheet();$("#mnErr").onclick=()=>openErr(k,itemId);return}
  const L1=a=>a.map((x,i)=>`<label class="chk" style="margin:4px 0"><input type="checkbox">${esc(x)}</label>`).join("");
  const notes=mnNotes.filter(n=>n.k===k).sort((a,b)=>b.at-a.at);
  openSheet(`<h3>📘 ${esc(k)}</h3><div class="m">${esc(t("grp_"+M.grp))}</div>
   <label>${esc(t("mnWhat"))}</label><div>${esc(mx(M.what))}</div>
   <label>${esc(t("mnWhen"))}</label><div>${esc(mx(M.when))}</div>
   <div class="actions"><a class="btn" href="${esc(M.p.u)}" target="_blank" rel="noopener">${esc(t("mnPortal"))} · ${esc(M.p.n)}</a></div>
   <h2>${esc(t("mnDocs"))}</h2>${L1(mx(M.docs)||[])}
   <h2>${esc(t("mnSteps"))}</h2><ol style="margin:4px 0 0 20px;padding:0">${(mx(M.steps)||[]).map(s=>`<li style="margin-bottom:8px">${esc(s)}</li>`).join("")}</ol>
   <div class="m">${esc(t("mnPortalNote"))}</div>
   <h2>${esc(t("mnMist"))}</h2><ul style="margin:4px 0 0 20px;padding:0">${(mx(M.mist)||[]).map(s=>`<li style="margin-bottom:6px">⚠ ${esc(s)}</li>`).join("")}</ul>
   <h2>${esc(t("mnLate"))}</h2><div>${esc(mx(M.late))}</div>
   <h2>${esc(t("mnProof"))}</h2><div class="note" style="background:var(--green-soft)">${esc(mx(M.proof))}</div>
   <h2>${esc(t("mnTeam"))}</h2>${notes.map(n=>`<div class="note" style="margin-bottom:6px">💡 ${esc(n.text)}<div class="m">${esc(n.by==="local"?t("you"):nm(n.by))} · ${esc(new Date(n.at).toLocaleDateString())}</div></div>`).join("")}
   <div style="display:flex;gap:6px;margin-top:6px"><input id="mnTip" placeholder="${esc(t("mnTeamPh"))}"><button class="btn ghost" id="mnTipB">+</button></div>
   <div class="actions"><button class="btn red" id="mnErr">${esc(t("erB"))}</button><button class="btn ghost" id="mnX">${esc(t("close"))}</button></div>`,{k:"manual",id:k,item:itemId});
  $("#mnX").onclick=()=>itemId?openDetail(itemId):closeSheet();$("#mnErr").onclick=()=>openErr(k,itemId);
  $("#mnTipB").onclick=async()=>{const v=$("#mnTip").value.trim();if(!v)return;await mnAddNote(k,v);openManual(k,itemId)};
}
/* ---------- 🆘 error helper ---------- */
async function erImgOk(){try{return!!(sampleCap&&sampleCap.limits&&(await sampleCap.limits()).images)}catch(e){return false}}
function openErr(k,itemId,caseId){
  const it=itemId?items.find(x=>x.id===itemId):null;const c=caseId?erCases.find(x=>x.id===caseId):null;
  const kk=k||(c&&c.k)||"";
  const past=erCases.filter(x=>x.answer&&x.id!==caseId&&(!kk||x.k===kk)).sort((a,b)=>((b.worked||[]).length-(a.worked||[]).length)||(b.at-a.at)).slice(0,5);
  openSheet(`<h3>${esc(t("erT"))}</h3><div class="m">${esc(t("erTxt"))}</div>
   ${it?`<div class="note">${esc(it.name)} · ${esc(it.client||"")} · ${esc(it.period||"")}</div>`:""}
   <label>${esc(t("erWhich"))}</label><select id="erK"><option value="">${esc(t("erAny"))}</option>${Object.keys(MANUAL).map(x=>`<option value="${x}" ${x===kk?"selected":""}>${esc(x)}</option>`).join("")}</select>
   <label>${esc(t("erDesc"))}</label><textarea id="erD" rows="3" placeholder="${esc(t("erDescPh"))}">${esc(c?c.desc:"")}</textarea>
   ${c?(c.imgs||[]).map(id=>`<img src="/_blob/${esc(id)}" style="max-width:100%;border:1px solid var(--line);border-radius:8px;margin-top:6px" alt="">`).join(""):`<label>${esc(t("erImg"))}</label><input type="file" id="erF" accept="image/*" multiple>`}
   <div class="err" id="ferr"></div>
   ${c?"":`<div class="actions"><button class="btn" id="erGo">${esc(t("erGo"))}</button><button class="btn ghost" id="erSv">${esc(t("erSave"))}</button><button class="btn ghost" id="erX">${esc(t("close"))}</button></div>`}
   <div id="erAns" style="white-space:pre-wrap;margin-top:10px">${c&&c.answer?esc(c.answer):""}</div>
   <div id="erAfter">${c?erAfterHtml(c):""}</div>
   ${past.length?`<h2>${esc(t("erPast"))}</h2>`+past.map(x=>`<div class="item erPast" data-id="${esc(x.id)}"><div class="main"><div class="t">${esc((x.desc||"").slice(0,80)||"—")}</div><div class="m">${esc(x.k||"")} · ${esc(new Date(x.at).toLocaleDateString())}</div></div>${(x.worked||[]).length?`<span class="badge b-filed_proof">${esc(t("erWorkedBy",{n:x.worked.length}))}</span>`:""}</div>`).join(""):""}
   ${c?`<div class="actions"><button class="btn ghost" id="erX">${esc(t("close"))}</button></div>`:""}`,{k:"err",id:caseId||null,mk:k,item:itemId});
  $("#erX").onclick=()=>itemId?openDetail(itemId):(k?openManual(k):closeSheet());
  document.querySelectorAll(".erPast").forEach(r=>r.onclick=()=>openErr(null,null,r.dataset.id));
  if(c){erWireAfter(c);return}
  let saved=null;
  const collect=async(answer)=>{const files=[...($("#erF").files||[])];const imgs=[];
    if(assets)for(const f of files.slice(0,3)){try{const r=await assets.upload(f);imgs.push(r.id)}catch(e){}}
    return{k:$("#erK").value,desc:$("#erD").value.trim(),imgs,answer:answer||"",item:itemId||"",client:it?it.client||"":"",by:me.id||"local",at:Date.now(),worked:[],solved:false}};
  $("#erSv").onclick=async()=>{const d=$("#erD").value.trim(),f=$("#erF").files;if(!d&&!(f&&f.length)){$("#ferr").textContent=t("erNeed");return}
    $("#erSv").disabled=true;const cc=await collect($("#erAns").textContent);if(saved)cc.id=saved;saved=await erSaveCase(cc);toast(t("erSaved"));$("#erSv").disabled=false};
  $("#erGo").onclick=async()=>{const d=$("#erD").value.trim(),files=[...($("#erF").files||[])];
    if(!d&&!files.length){$("#ferr").textContent=t("erNeed");return}
    if(!sampleCap){$("#erAns").textContent=t("erNoAi");return}
    const imgOk=files.length?await erImgOk():true;
    const out=$("#erAns");out.textContent=t("erWait");$("#erGo").disabled=true;$("#ferr").textContent=files.length&&!imgOk?t("erNoImg"):"";
    const key=$("#erK").value,M=MANUAL[key];
    const langName={hi:"simple Hindi (Devanagari)",en:"simple English",zh:"simple Chinese"}[lang];
    const prev=erCases.filter(x=>x.answer&&(x.worked||[]).length&&(!key||x.k===key)).slice(0,4).map(x=>({error:x.desc,fix_that_worked:x.answer.slice(0,600)}));
    const prompt=`You are a senior compliance executive in an Indian CA firm helping a junior who hit an error on a government portal (GST, income-tax e-filing/TRACES, MCA V3, EPFO, ESIC, DGFT, FSSAI or a state portal).
Answer in ${langName}. Format:
1) एरर का मतलब / What the error means — one or two lines, quote the exact error text you can read.
2) सबसे आम कारण / Most likely causes — up to 3.
3) ठीक करने के स्टेप / Steps to fix — numbered, practical, portal menu names in English.
4) फिर भी न हो तो / If it still fails — e.g. clear cache/other browser, wait for portal, raise a grievance/helpdesk ticket, ask a senior.
Rules: Only state what the screenshot/description supports or what is standard portal behaviour. If the image is unclear or you are not sure, say so and say what extra detail to send. Never ask for or repeat passwords/OTPs. Do not invent deadlines, penalties or legal sections. Keep it under 15 lines.
Compliance: ${key||"unknown"}${M?` — ${M.what.en}. Normal steps: ${M.steps.en.join(" | ")}`:""}
${it?`Entry: ${it.name}, period ${it.period||""}, due ${it.dueDate||""}`:""}
Fixes that worked for this team before: ${JSON.stringify(prev)}
Junior's description: ${d||"(only screenshot)"}`;
    try{const opts={modelTier:"default",onText:x=>{out.textContent=x.text}};if(files.length&&imgOk)opts.images=files.slice(0,3);
      const r=await sampleCap(prompt,opts);out.textContent=r.text;
      const cc=await collect(r.text);saved=await erSaveCase(cc);const sc=Object.assign({id:saved},cc);$("#erAfter").innerHTML=`<div class="m">${esc(t("erNote"))}</div>`+erAfterHtml(sc);erWireAfter(sc)}
    catch(e){out.textContent=e&&e.code==="not_granted"?"":t("luAskErr")}
    $("#erGo").disabled=false};
}
function erAfterHtml(c){const w=(c.worked||[]);const mine=w.includes(me.id||"local");
  return `<div class="actions">${mine?`<span class="badge b-filed_proof">${esc(t("erWorkedBy",{n:w.length}))}</span>`:`<button class="btn green" id="erW">${esc(t("erWorked"))}</button>`}</div>`}
function erWireAfter(c){const b=$("#erW");if(b)b.onclick=async()=>{const w=(c.worked||[]).slice();const u=me.id||"local";if(!w.includes(u))w.push(u);c.worked=w;c.solved=true;await erSaveCase(c);$("#erAfter").innerHTML=erAfterHtml(c)}}
function openErrList(){
  const L2=erCases.slice().sort((a,b)=>b.at-a.at);
  openSheet(`<h3>${esc(t("erAll"))}</h3>${L2.map(x=>`<div class="item erPast" data-id="${esc(x.id)}"><div class="main"><div class="t">${esc((x.desc||"").slice(0,90)||"—")}</div><div class="m">${esc(x.k||"")}${x.client?" · "+esc(x.client):""} · ${esc(x.by==="local"?t("you"):nm(x.by))} · ${esc(new Date(x.at).toLocaleDateString())}</div></div><span class="badge ${x.solved?"b-filed_proof":"b-late"}">${esc(x.solved?t("erSolvedT"):t("erOpenT"))}</span></div>`).join("")||`<div class="empty">${esc(t("nothing"))}</div>`}
   <div class="actions"><button class="btn red" id="erNew2">${esc(t("erB"))}</button><button class="btn ghost" id="erX">${esc(t("close"))}</button></div>`,{k:"errlist"});
  $("#erX").onclick=closeSheet;$("#erNew2").onclick=()=>openErr(null,null);
  document.querySelectorAll(".erPast").forEach(r=>r.onclick=()=>openErr(null,null,r.dataset.id));
}
